/**
 * UniversalController type definiton test
 */
import { type ModuleDefinition, UniversalApp } from 'cerebral'

const appModule: ModuleDefinition = {
  state: {
    foo: 0,
    isAwesome: false,
  },
  sequences: {
    aSequence: [],
  },
}

const app = UniversalApp(appModule)

// runSequence
app
  .runSequence(
    [
      function myAction({ store, props }: any) {
        store.set('isAwesome', props.isAwesome)
      },
    ],
    {
      isAwesome: true,
    }
  )
  .then(() => {
    // I am done running
  })

// setState
app.setState('foo', 123)

app.runSequence('aSequence', { isAwesome: true }).then(() => {
  // I am done running
})

// getChanges
app.runSequence('aSequence', { isAwesome: true }).then(() => {
  app.getChanges() // {"isAwesome": true}
})

// getScript

app
  .run(
    [
      function myAction({ store, props }: any) {
        store.set('isAwesome', props.isAwesome)
      },
    ],
    {
      isAwesome: true,
    }
  )
  .then(() => {
    app.getScript()
  })
